// Derived source assertions from the existing committed OpenAlex archive.
// No provider requests, new identity registry, review writes or invented links.
let
    TextValue=(R as record,K as text) as text => let V=Record.FieldOrDefault(R,K,null) in if V=null then "" else if Value.Is(V,type text) then V else error "Relationship text schema drift",
    Records=(R as record,K as text) as list => let V=Record.FieldOrDefault(R,K,{}) in if V=null then {} else if Value.Is(V,type list) and List.AllTrue(List.Transform(V,each Value.Is(_,type record))) then V else error "Relationship list schema drift",
    ProviderID=(S as text,Kind as text) as text => let Prefix="https://openalex.org/"&Kind, N=if Text.StartsWith(S,Prefix) then Text.Range(S,Text.Length(Prefix)) else "" in if Text.StartsWith(S,Prefix) and N<>null and N<>"" and Text.Select(N,{"0".."9"})=N then S else "",
    DOI=(S as text) as text => let T=Text.Lower(Text.Trim(S)),Prefixes={"https://doi.org/","http://doi.org/","http://dx.doi.org/","https://dx.doi.org/"}, P=List.First(List.Select(Prefixes,each Text.StartsWith(T,_)),null),V=if P=null then T else Text.Range(T,Text.Length(P)) in if Text.StartsWith(V,"10.") and Text.Contains(V,"/") then V else "",
    ORCIDStatus=(S as text) as text => let T=Text.Replace(Text.Replace(S,"https://orcid.org/",""),"http://orcid.org/",""),Digits=Text.Replace(T,"-",""),Shape=Text.Length(T)=19 and Text.Middle(T,4,1)="-" and Text.Middle(T,9,1)="-" and Text.Middle(T,14,1)="-" and Text.Length(Digits)=16 and Text.Select(Text.Start(Digits,15),{"0".."9"})=Text.Start(Digits,15),Total=if Shape then List.Accumulate(Text.ToList(Text.Start(Digits,15)),0,(A,C)=>(A+Number.FromText(C))*2) else 0,Check=Number.Mod(12-Number.Mod(Total,11),11),Expected=if Check=10 then "X" else Text.From(Check) in if S="" then "Absent" else if Shape and Text.End(T,1)=Expected then "Valid syntax; unauthenticated" else "Invalid",
    Observations=Table.ToRecords(OpenAlexCommittedObservations),
    WorkRecords=List.Buffer(List.Transform(Observations,(R)=>let E=Json.Document(R[MetadataJSON]),B=Binary.FromText(E[raw_response_base64],BinaryEncoding.Base64),W=Json.Document(B),Valid=E[kind]="openalex_retained_observation_v1" and E[source]="OpenAlex" and E[http_status]=200 and E[work_id]=W[id] and ProviderID(W[id],"W")<>"" and DOI(E[requested_doi])=DOI(W[doi]) and DOI(W[doi])<>"" and Binary.Length(B)=E[raw_byte_count] in if Valid then [Envelope=E,Work=W] else error "Retained relationship work identity drift")),
    WorkIDs=List.Transform(WorkRecords,each [Work][id]),
    UniqueWorks=if List.Count(List.Distinct(WorkIDs))=List.Count(WorkIDs) then WorkRecords else error "Duplicate retained relationship work",
    Authors=List.Buffer(List.Combine(List.Transform(UniqueWorks,(R)=>List.Transform(Records(R[Work],"authorships"),(A)=>let X=Record.FieldOrDefault(A,"author",[]) in [ID=ProviderID(TextValue(X,"id"),"A"),ORCID=TextValue(X,"orcid")])))),
    Conflicts=List.Buffer(List.Select(List.Distinct(List.Transform(Authors,each [ID])),(ID)=>let Values=List.Distinct(List.Transform(List.Select(Authors,each [ID]=ID and Text.StartsWith(ORCIDStatus([ORCID]),"Valid")),each Text.Replace(Text.Replace([ORCID],"https://orcid.org/",""),"http://orcid.org/",""))) in List.Count(Values)>1)),
    ActorKey=(ID as text) as text => let Values=List.Distinct(List.Transform(List.Select(Authors,each [ID]=ID and Text.StartsWith(ORCIDStatus([ORCID]),"Valid")),each Text.Replace(Text.Replace([ORCID],"https://orcid.org/",""),"http://orcid.org/",""))),O=if List.Count(Values)=1 then Values{0} else "",Owners=if O="" then {} else List.Distinct(List.Transform(List.Select(Authors,each [ID]<>"" and Text.Replace(Text.Replace([ORCID],"https://orcid.org/",""),"http://orcid.org/","")=O),each [ID])) in if O<>"" and List.Count(Owners)=1 then "orcid:"&O else ID,
    PairRows=(IDs as list) as list => List.Combine(List.Transform(List.Positions(IDs),(I)=>List.Transform(List.Skip(IDs,I+1),(B)=>[A=IDs{I},B=B]))),
    Output=List.Buffer(List.Combine(List.Transform(UniqueWorks,(R)=>let
        E=R[Envelope],W=R[Work],D=DOI(W[doi]),
        Add=(Kind as text,F as text,T as text,FL as text,TL as text,O as text,State as text,ROR as text) as record => [EvidenceKey=Text.Combine({W[id],Kind,F,T},"|"),RelationshipKind=Kind,SourceWorkID=W[id],PublicationDOI=D,PublicationPMID="",ReferenceType="",FromKey=F,ToKey=T,FromLabel=FL,ToLabel=TL,ORCID=O,ORCIDStatus=ORCIDStatus(O),ROR=ROR,IdentityStatus=State,SourceURL=W[id],ObservedUTC=E[observed_utc],RawSHA256=E[raw_response_sha256],SourceVersion=E[raw_response_sha256],ReviewState="Not reviewed",AuthenticationState="Not authenticated"],
        As=Records(W,"authorships"),
        ARecords=List.Buffer(List.Transform(List.Positions(As),(I)=>let A=As{I},X=Record.FieldOrDefault(A,"author",[]),ID=ProviderID(TextValue(X,"id"),"A"),State=if ID="" then "Unresolved identity" else if List.Contains(Conflicts,ID) then "Conflicting identifiers" else "Source-supported",Key=if ID="" then W[id]&"/unresolved-author/"&Text.From(I+1) else ActorKey(ID),Name=TextValue(X,"display_name"),O=TextValue(X,"orcid") in [Key=Key,ProviderID=ID,Name=Name,ORCID=O,State=State,Institutions=Records(A,"institutions")])),
        Aliases=List.Transform(List.Select(ARecords,each [ProviderID]<>"" and Text.StartsWith(ORCIDStatus([ORCID]),"Valid") and Text.StartsWith([Key],"orcid:")),each Add("identity_alias",[ProviderID],[Key],[Name],[ORCID],[ORCID],[State],"")),
        Authorships=List.Transform(ARecords,each Add("authorship","doi:"&D,[Key],"",[Name],[ORCID],[State],"")),
        Affiliations=List.Combine(List.Transform(ARecords,(A)=>List.Transform(List.Select(A[Institutions],each ProviderID(TextValue(_,"id"),"I")<>""),(I)=>Add("publication_affiliation",A[Key],I[id],A[Name],TextValue(I,"display_name"),A[ORCID],A[State],TextValue(I,"ror"))))),
        Good=List.Select(ARecords,each [State]="Source-supported"),AIDs=List.Sort(List.Distinct(List.Transform(Good,each [Key]))),
        NameFor=(ID as text) as text => List.First(List.Select(Good,each [Key]=ID))[Name],
        Coauthors=List.Transform(PairRows(AIDs),each Add("coauthorship",[A],[B],NameFor([A]),NameFor([B]),"","Source-supported","")),
        IIDs=List.Sort(List.Distinct(List.Transform(Affiliations,each [ToKey]))),
        IName=(ID as text) as text => List.First(List.Select(Affiliations,each [ToKey]=ID))[ToLabel],
        Institutions=List.Transform(PairRows(IIDs),each Add("institution_cooccurrence",[A],[B],IName([A]),IName([B]),"","Source-supported","")),
        Awards=List.RemoveNulls(List.Transform(Records(W,"awards"),(A)=>let ID=ProviderID(TextValue(A,"id"),"G"),FID=ProviderID(TextValue(A,"funder_id"),"F"),Number=TextValue(A,"funder_award_id"),Key=if ID<>"" then ID else if FID<>"" and Number<>"" then FID&"/award/"&Number else "" in if Key="" then null else Add("publication_award","doi:"&D,Key,"",TextValue(A,"funder_display_name")&" | "&Number,"","Source-supported","")))
        in {Add("publication","doi:"&D,W[id],"","","","Source-supported","")} & Aliases & Authorships & Affiliations & Coauthors & Institutions & Awards))),
    StudyRows=__STUDY_REGISTER_SOURCE__,
    StudySite=__STUDY_SITE_URL__,
    StudyRoot=SharePoint.Contents(__STUDY_SITE_URL__,[ApiVersion=15]),
    ReadStudy=(URL as text) as binary => let Site=Text.BeforeDelimiter(URL,"/Documents/"),Parts=Text.Split(Text.AfterDelimiter(URL,Site&"/"),"/"),Root=if Site=StudySite then StudyRoot else error "Study archive site drift",Folder=List.Accumulate(List.RemoveLastN(Parts,1),Root,(T,N)=>let Matches=Table.SelectRows(T,each [Name]=N) in if Table.RowCount(Matches)=1 and Value.Is(Matches{0}[Content],type table) then Matches{0}[Content] else error "Study archive folder missing or duplicated"),Matches=Table.SelectRows(Folder,each [Name]=List.Last(Parts)) in if Table.RowCount(Matches)=1 and Value.Is(Matches{0}[Content],type binary) then Binary.Buffer(Matches{0}[Content]) else error "Study archive file missing or duplicated",
    StudyEvidence=List.Combine(List.Transform(Table.ToRecords(StudyRows),(R)=>let SE=Json.Document(ReadStudy(R[ArchiveFileURL])),S=SE[response][body],N=S[protocolSection][identificationModule][nctId],Valid=SE[response][statusCode]=200 and SE[requested_id]=R[NCTId] and N=R[NCTId] and R[SourceKey]="clinicaltrials.gov:"&N,Refs=if Valid then Records(Record.FieldOrDefault(S[protocolSection],"referencesModule",[]),"references") else error "Study source identity drift",Kept=List.Select(Refs,each List.Contains({"RESULT","DERIVED"},TextValue(_,"type")) and TextValue(_,"pmid")<>"" and Text.Select(TextValue(_,"pmid"),{"0".."9"})=TextValue(_,"pmid")) in List.Transform(Kept,(Ref)=>[EvidenceKey=Text.Combine({R[SourceKey],"publication_study_reference","pmid:"&Ref[pmid],R[SourceKey]},"|"),RelationshipKind="publication_study_reference",SourceWorkID=R[SourceKey],PublicationDOI="",PublicationPMID=Ref[pmid],ReferenceType=TextValue(Ref,"type"),FromKey="pmid:"&Ref[pmid],ToKey=R[SourceKey],FromLabel="",ToLabel=N,ORCID="",ORCIDStatus="Absent",ROR="",IdentityStatus="Source-supported",SourceURL=R[SourceURL],ObservedUTC=R[SourceObservedUTC],RawSHA256=R[SourcePayloadSHA256],SourceVersion=R[SourcePayloadSHA256],ReviewState="Not reviewed",AuthenticationState="Not authenticated"]))),
    PubMedProjector=__PUBMED_RELATIONSHIP_FUNCTION__,
    // Native deployments may expose a source-parameter function; portable source exposes a table.
    PubMedHistory=if Value.Is(RetainedSourceObservations,type function) then RetainedSourceObservations("PubMed") else Table.SelectRows(RetainedSourceObservations,each [Source]="PubMed"),
    PubMedEvidence=PubMedProjector(PubMedHistory,RetainedArchiveFiles),
    Columns={"EvidenceKey","RelationshipKind","SourceWorkID","PublicationDOI","PublicationPMID","ReferenceType","FromKey","ToKey","FromLabel","ToLabel","ORCID","ORCIDStatus","ROR","IdentityStatus","SourceURL","ObservedUTC","RawSHA256","SourceVersion","ReviewState","AuthenticationState"},
    Rows=Table.Buffer(Table.FromRecords(Output & StudyEvidence & PubMedEvidence,Columns,MissingField.Error)),
    Groups=Table.Group(Rows,{"EvidenceKey"},{{"Rows",each Table.Distinct(_),type table}}),
    Checked=if List.AllTrue(List.Transform(Groups[Rows],each Table.RowCount(_)=1)) then Table.Distinct(Rows,{"EvidenceKey"}) else error "Conflicting repeated relationship assertion",
    Result=Table.TransformColumnTypes(Checked,List.Transform(Columns,each {_,type text}))
in Result
